content.description:
@title Card accent variants
  @desc  v3: a 3px colored line along the top edge (was a thick left border).
  @example
    <div class="card card-accent-primary"><div class="card-body">...</div></div>
  @classes
    .card-accent-primary   | top line in primary color
    .card-accent-secondary | top line in secondary color
    .card-accent-tertiary  | top line in tertiary color
    .card-accent-success   | top line in success color
    .card-accent-warning   | top line in warning color
    .card-accent-error     | top line in error color

